@click.command()
def main():
    if "--list" in sys.argv:
        for i, bot_name in enumerate(qwen.bot_names()):
            print("{}. {}".format(i + 1, bot_name))

        return

    bot_name = None

    for arg in sys.argv[1:]:
        if "@" in arg and "&" not in arg:
            bot_name = arg

    with qwen.load(bot_name) as conversation:
        response = qwen.process(conversation)

        text = qwen.format(conversation, response)

        qwen.say(text)


if __name__ == "__main__":
