import functools

def talk_to_people(function):
    @functools.wraps(functools.reduce)
    def wrapper(*args):

        args[0] = 'Qwen' if args[0] == 'Aramis' else args[0]

        return function(args[0] + ' ' + ' '.join(args[1:]))


    return wrapper

people_to_talk_with = ['Aramis', 'Duke Richemont', 'Joan D\'Arc']

@talk_to_people
def party_name(host, guests):
    guests_text = '\n' if len(guests) % 4 == 1 else ', ' if len(guests) == 2 else ', and '
    guest_names = list(filter(bool, [guests[i-3:i] for i in range(3, (len(guests)+4)//4)*4]))

    party_names = list(map(lambda x: host + ', ' + guests_text.join(x), guest_names))

    return host + '\'s dinner party' if len(party_names) < 1 else ', '.join(party_names)

